    otherLegalTerms: 'Other Legal Terms',
    disclaimerTitle: 'Disclaimer',
    disclaimerText: 'DeHub wey operate a protocol a go decentralize. We give out platform "a go" no guarantee, no warranty. Because wey decentralize, we no can promise dat we go be always available or dat we go have specific performance metric.',
    limitationOfLiability: 'Limitation of Liability',
